"use client";
import {useState} from "react"; import Header from "@/components/Header"; import Footer from "@/components/Footer"; import Hero from "@/components/Hero"; import {ProductCard} from "@/components/Cards"; import {products,img} from "@/components/siteData";
export default function Products(){const [category,setCategory]=useState("All");const cats=["All","HDPE","Blue","PPR","Sanitary","Electrical","Tanks","Roofing"];const filtered=category==="All"?products:products.filter(p=>p[1]===category);return <><Header/><Hero eyebrow="PRODUCTS" title="OUR PRODUCTS" description="High-quality piping and water storage solutions for a stronger, more sustainable Philippines." image={img.hero}/><section className="products-page"><aside className="product-sidebar"><h3>Product Categories</h3>{cats.map(c=><button key={c} className={category===c?"selected":""} onClick={()=>setCategory(c)}>{c} <span>›</span></button>)}<div className="help-box"><div>🎧</div><h4>Need Help?</h4><p>Our team is ready to assist you in finding the right product.</p><a href="/contact">Contact Us →</a></div></aside><main className="products-main"><div className="page-heading-row"><div><small>FEATURED PRODUCT CATEGORIES</small><h2>Products</h2></div><span>{filtered.length} Products</span></div><div className="product-grid">{filtered.map(([title,,desc,image])=><ProductCard key={title} image={image} title={title} description={desc}/>)}</div></main></section><Footer/></>}
