export function ProductCard({image,title,description}:{image:string;title:string;description?:string}){return <article className="product-card"><div className="card-image"><img src={image} alt={title}/></div><div className="card-content"><h3>{title}</h3>{description&&<p>{description}</p>}<button>Download Brochure ↓</button></div></article>}
export function SolutionCard({image,title,description,icon}:{image:string;title:string;description:string;icon:string}){return <article className="solution-card"><div className="solution-icon">{icon}</div><div className="solution-content"><h3>{title}</h3><p>{description}</p><a href="#">Learn More →</a></div><img src={image} alt={title}/></article>}
